    /**
     * Use the RepresentanteLegal relation RepresentanteLegal object
     *
     * @see       useQuery()
     *
     * @param     string $relationAlias optional alias for the relation,
     *                                   to be used as main alias in the secondary query
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return   RepresentanteLegalQuery A secondary query class using the current class as primary query
     */
    public function useRepresentanteLegalQuery($relationAlias = null, $joinType = Criteria::LEFT_JOIN)
    {
        return $this
            ->joinRepresentanteLegal($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'RepresentanteLegal', 'RepresentanteLegalQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   ServicioInteresados $servicioInteresados Object to remove from the list of results
     *
     * @return ServicioInteresadosQuery The current query, for fluid interface
     */
    public function prune($servicioInteresados = null)
    {
        if ($servicioInteresados) {
            $this->addUsingAlias(ServicioInteresadosPeer::SERVICIOINTERESADO_ID, $servicioInteresados->getServiciointeresadoId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

